#include <WiFi.h>
#include <Wire.h>
#include <SPI.h>
#include <Adafruit_GFX.h>
#include <Adafruit_ST7789.h>
#include <DHT.h>
#include <LiquidCrystal_I2C.h>

DHT dht(14, DHT11);
LiquidCrystal_I2C lcd(0x27, 16, 2);
Adafruit_ST7789 tft(-1, 9, 10);

void setup() {
  Serial.begin(115200);
  dht.begin();
  pinMode(13, INPUT);
  Wire.begin(8, 18);
  lcd.init();
  lcd.backlight();
  SPI.begin(12, -1, 11, -1);
  tft.init(240, 240, SPI_MODE2);
  ledcAttach(41, 50, 16);
  ledcAttach(42, 50, 16);
  WiFi.softAP("ESP32-Robot", "12345678");
}

void loop() {
  lcd.setCursor(0, 1);
  lcd.print(digitalRead(13) ? "Motion!" : "Safe   ");
  tft.fillScreen(digitalRead(13) ? 0xF800 : 0x07E0);
  delay(1000);
}
